INSERT INTO `Destinations` (`id`, `name`, `slug`, `subtitle`, `region`, `tagline`, `shortDescription`, `description`, `heroImage`, `gallery`, `latitude`, `longitude`, `bestTimeToVisit`, `howToReach`, `idealDuration`, `weatherInfo`, `temp`, `humidity`, `scubaScore`, `waterTemp`, `clarity`, `rating`, `reviewsCount`, `startingPrice`, `highlights`, `stays`, `packages`, `faq`, `thingsToDo`, `isFeatured`, `status`, `createdAt`, `updatedAt`) VALUES
(1, 'Port Blair', 'port-blair', NULL, NULL, NULL, 'The historic capital of Andaman with Cellular Jail and serene harbors.', 'Port Blair serves as the gateway to the Andaman & Nicobar Islands. Rich in history, marine life, and coastal vistas.', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?auto=format&fit=crop&w=1200&q=80', '[]', 11.6234, 92.7265, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.8, 0, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'ACTIVE', '2026-08-18 13:37:31.077 +00:00', '2026-08-18 13:37:31.077 +00:00'),
(2, 'Havelock Island (Swaraj Dweep)', 'havelock-island', NULL, NULL, NULL, 'Home to world-famous Radhanagar Beach and turquoise coral reefs.', 'Havelock (Swaraj Dweep) is tropical paradise personified. Azure waters, scuba diving, and white sand beaches await.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80', '[]', 11.9667, 92.9833, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.8, 0, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'ACTIVE', '2026-08-18 13:37:31.085 +00:00', '2026-08-18 13:37:31.085 +00:00'),
(3, 'Neil Island (Shaheed Dweep)', 'neil-island', NULL, NULL, NULL, 'The vegetable bowl of Andaman with natural rock bridges and quiet shores.', 'Neil Island (Shaheed Dweep) offers peaceful village life, coral bridge formations at Laxmanpur Beach, and relaxed vibes.', 'https://images.unsplash.com/photo-1519046904884-53103b34b206?auto=format&fit=crop&w=1200&q=80', '[]', 11.8333, 93.05, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.8, 0, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'ACTIVE', '2026-08-18 13:37:31.092 +00:00', '2026-08-18 13:37:31.092 +00:00'),
(4, 'Baratang Island', 'baratang-island', NULL, NULL, NULL, 'Famous for limestone caves, mangrove creeks, and mud volcanoes.', 'Baratang Island offers dense tropical jungle treks, boat rides through mangrove tunnels, and limestone cave exploration.', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=80', '[]', 12.1167, 92.7833, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.8, 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, 'ACTIVE', '2026-08-18 13:37:31.099 +00:00', '2026-08-18 13:37:31.099 +00:00'),
(5, 'Diglipur', 'diglipur', NULL, NULL, NULL, 'Pristine eco-tourism hotspot with Saddle Peak and turtle nesting.', 'Diglipur offers a unique offbeat experience in North Andaman. Climb Saddle Peak, witness turtle nesting at Kalipur, or cross Ross & Smith sandbar.', 'https://images.unsplash.com/photo-1610014766858-69315bc32b4f?auto=format&fit=crop&w=1200&q=80', '[]', 13.2667, 93.0167, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.8, 0, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'ACTIVE', '2026-08-27 04:58:53', '2026-08-27 04:58:53'),
(6, 'Great Nicobar', 'great-nicobar', NULL, NULL, NULL, 'Remote biosphere reserve with rare wildlife and Indira Point.', 'Great Nicobar is the southernmost island of the archipelago, home to Galathea National Park, pristine rain forests, and Indira Point.', 'https://images.unsplash.com/photo-1510414842594-a61c69b5ae57?auto=format&fit=crop&w=1200&q=80', '[]', 7, 93.8, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4.8, 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, 'ACTIVE', '2026-08-27 04:58:53', '2026-08-27 04:58:53');
