INSERT INTO `Cruises` (`id`, `name`, `slug`, `type`, `shortDescription`, `description`, `heroImage`, `gallery`, `duration`, `departurePoint`, `capacity`, `price`, `features`, `inclusions`, `exclusions`, `status`, `createdAt`, `updatedAt`) VALUES
(2, 'Andaman Sunset Sail', 'andaman-sunset-sail', 'SUNSET_SAIL', 'Golden hour luxury sailing with live acoustic music and mocktails.', 'Watch the Andaman horizon transform as the sun disappears into the sea. A timeless experience.', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80', '[]', '2 Hours', 'Port Blair Harbour', 40, 2500, '["Scenic Ocean Views","Golden Hour Experience"]', '["Welcome drink","Snacks","Safety vest"]', '["Personal expenses"]', 'ACTIVE', '2026-08-27 04:58:53', '2026-08-27 04:58:53'),
(3, 'Private Ocean Charter', 'private-ocean-charter', 'PRIVATE', 'Exclusive private yacht charter for groups and events.', 'Make the ocean your own with a private charter designed entirely around your group.', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=80', '[]', 'Half Day / Full Day', 'Port Blair / Havelock', 12, 15000, '["Exclusive Private Booking","Custom Route Options"]', '["Yacht rental","Safety gear"]', '["Food & Beverages"]', 'ACTIVE', '2026-08-27 04:58:53', '2026-08-27 04:58:53'),
(4, 'Havelock Island Sightseeing', 'havelock-island-sightseeing', 'SIGHTSEEING', 'Coastal sightseeing cruise around Havelock Island.', 'Explore the stunning coastline of Havelock Island from the water — reefs, beaches and more.', 'https://images.unsplash.com/photo-1510414842594-a61c69b5ae57?auto=format&fit=crop&w=1200&q=80', '[]', '2–4 Hours', 'Havelock Island (Swaraj Dweep)', 30, 1800, '["Coastal Views","Coral Reef Spotting"]', '["Cruise ticket","Safety vest"]', '["Guides fee"]', 'ACTIVE', '2026-08-27 04:58:54', '2026-08-27 04:58:54'),
(5, 'Couple Escape Cruise', 'couple-escape-cruise', 'COUPLE', 'Romantic private ocean getaway for couples.', 'A private ocean experience crafted for couples — sunsets, calm seas and unforgettable moments.', 'https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=1200&q=80', '[]', '2–3 Hours', 'Port Blair / Havelock', 10, 4500, '["Couple-Focused Romance","Golden Hour Sunset Deck"]', '["Mocktails & treats","Safety gear"]', '["Candlelight setup fee"]', 'ACTIVE', '2026-08-27 04:58:54', '2026-08-27 04:58:54'),
(6, 'Family Ocean Adventure', 'family-ocean-adventure', 'FAMILY', 'Family adventure cruise with scenic coastline views.', 'Take the whole family on a memorable ocean journey around the beautiful Andaman coastline.', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1200&q=80', '[]', '2–4 Hours', 'Port Blair', 50, 1600, '["Family-Friendly Deck","Child Safety Vests"]', '["Cruise ticket","Safety vests","Light snacks"]', '["Pick up / Drop off"]', 'ACTIVE', '2026-08-27 04:58:54', '2026-08-27 04:58:54'),
(7, 'Luxury Sea Experience', 'luxury-sea-experience', 'LUXURY', 'Ultra comfortable luxury cruise expedition.', 'A premium full-day ocean journey with elevated comfort, exclusive routes and curated service.', 'https://images.unsplash.com/photo-1567899378494-47b22a2ae96a?auto=format&fit=crop&w=1200&q=80', '[]', 'Full Day', 'Port Blair / Havelock', 25, 8500, '["Luxury AC Lounge","Gourmet Dining"]', '["Premium Lounge Access","Gourmet Buffet Lunch","Snorkeling"]', '["Alcoholic drinks"]', 'ACTIVE', '2026-08-27 04:58:54', '2026-08-27 04:58:54');
