INSERT INTO `Stays` (`id`, `name`, `slug`, `type`, `destinationId`, `shortDescription`, `description`, `heroImage`, `gallery`, `rating`, `reviewCount`, `pricePerNight`, `currency`, `guestCapacity`, `latitude`, `longitude`, `checkIn`, `checkOut`, `cancellationPolicy`, `status`, `featured`, `createdAt`, `updatedAt`) VALUES
(3, 'Taj Exotica Resort & Spa', 'taj-exotica-resort-spa', 'LUXURY_VILLA', 2, 'Occupying 46 acres of lush rainforest along Radhanagar Beach, Taj Exotica offers eco-luxury villas with private pools.', 'Set amidst 46 acres of coconut groves and rainforest on Radhanagar Beach, Taj Exotica Resort & Spa is the pinnacle of luxury hospitality in the Andaman Islands.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1200&q=85', '["https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1542718610-a1d656d1884c?auto=format&fit=crop&w=800&q=80"]', 4.9, 128, 32000, 'INR', 4, 11.9833, 92.95, '12:00 PM', '10:00 AM', NULL, 'ACTIVE', 1, '2026-10-03 14:50:02', '2026-10-03 14:50:02'),
(4, 'Barefoot at Havelock', 'barefoot-at-havelock', 'BOUTIQUE_RESORT', 2, 'Eco-chic luxury wooden cottages nestled beside Radhanagar Beach.', 'Set amidst tropical rainforest and steps away from turquoise waters, Barefoot offers unpretentious luxury and a rustic eco-friendly environment.', 'https://images.unsplash.com/photo-1542718610-a1d656d1884c?auto=format&fit=crop&w=1200&q=85', '[]', 4.8, 94, 18500, 'INR', 3, 11.97, 92.98, '12:00 PM', '10:00 AM', NULL, 'ACTIVE', 1, '2026-10-03 14:50:02', '2026-10-03 14:50:02'),
(5, 'SeaShell Havelock', 'seashell-havelock', 'BEACH_RESORT', 2, 'Modern luxury resort overlooking Govind Nagar beach.', 'Combining premium amenities, seaside dine-out bars and luxury spa treatment on Havelock island.', 'https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1200&q=80', '[]', 4.8, 75, 11200, 'INR', 2, 11.961, 92.991, '12:00 PM', '10:00 AM', NULL, 'ACTIVE', 0, '2026-10-03 14:50:03', '2026-10-03 14:50:03'),
(6, 'Symphony Palms Beach Resort', 'symphony-palms-resort', 'ECO_LODGE', 2, 'Unwind amidst palm-fringed private shores and nature walks.', 'Quiet beachfront cottages located right next to clear waters, perfect for families and couples.', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=80', '[]', 4.6, 62, 8900, 'INR', 2, 11.96, 92.99, '12:00 PM', '10:00 AM', NULL, 'ACTIVE', 0, '2026-10-03 14:50:03', '2026-10-03 14:50:03'),
(7, 'Summer Sands Beach Resort', 'summer-sands-resort', 'BOUTIQUE_RESORT', 3, 'Elegant oasis featuring expansive swimming pools and chic styling.', 'Unwind at our stylish boutique beach resort with premium room suites, outdoor pools, and dining options.', 'https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1200&q=80', '[]', 4.7, 48, 9500, 'INR', 3, 11.834, 93.055, '12:00 PM', '10:00 AM', NULL, 'ACTIVE', 0, '2026-10-03 14:50:03', '2026-10-03 14:50:03'),
(8, 'Munjoh Ocean Resort', 'munjoh-ocean-resort', 'LUXURY_VILLA', 2, 'Premium ocean-facing villas offering unparalleled solitude.', 'Tucked away in coco groves and pristine shores, Munjoh offers luxury seaside villas with curated personalized service.', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1200&q=80', '[]', 4.8, 52, 16500, 'INR', 4, 11.965, 92.985, '12:00 PM', '10:00 AM', NULL, 'ACTIVE', 1, '2026-10-03 14:50:03', '2026-10-03 14:50:03'),
(9, 'Welcomhotel by ITC Hotels, Bay Island', 'welcomhotel-bay-island-port-blair', 'HERITAGE_HOTEL', 1, 'Perched on a cliff overlooking the azure Bay of Bengal, built with native Padauk wood.', 'Designed by visionary architect Charles Correa using indigenous timber, Welcomhotel Bay Island overlooks the Andaman Sea with luxury dining, swimming pool, and harbor views.', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1200&q=85', '["https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=800&q=80"]', 4.8, 215, 14500, 'INR', 4, 11.6667, 92.7431, '12:00 PM', '10:00 AM', NULL, 'ACTIVE', 1, '2026-10-03 14:50:03', '2026-10-03 14:50:03'),
(10, 'Symphony Samudra Beachside Jungle Resort', 'symphony-samudra-port-blair', 'LUXURY_VILLA', 1, 'Nestled between Chidiyatapu rainforest and ocean shores with infinity sunset pool.', 'Symphony Samudra offers an unforgettable blend of lush tropical jungle retreats and oceanfront serenity near Chidiyatapu.', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1200&q=85', '[]', 4.9, 180, 12800, 'INR', 4, 11.505, 92.705, '12:00 PM', '10:00 AM', NULL, 'ACTIVE', 1, '2026-10-03 14:50:04', '2026-10-03 14:50:04'),
(11, 'Dew Dale Eco Resort', 'dew-dale-resort-baratang', 'ECO_LODGE', 4, 'Peaceful rural eco-resort surrounded by mangrove waterways and tribal forests.', 'The premier stay option on Baratang Island, offering rustic cottages, organic farm dining, and easy access to limestone caves.', 'https://images.unsplash.com/photo-1510414842594-a61c69b5ae57?auto=format&fit=crop&w=1200&q=85', '[]', 4.5, 65, 4500, 'INR', 3, 12.12, 92.78, '12:00 PM', '10:00 AM', NULL, 'ACTIVE', 0, '2026-10-03 14:50:04', '2026-10-03 14:50:04'),
(12, 'Pristine Beach Resort', 'pristine-beach-resort-diglipur', 'ECO_LODGE', 5, 'Eco-cottages on Kalipur Beach, famous for sea turtle nesting and Ross & Smith trips.', 'Situated right along Kalipur beach in North Andaman, ideal for climbing Saddle Peak, seeing turtle hatchlings, and sandbar walks.', 'https://images.unsplash.com/photo-1610014766858-69315bc32b4f?auto=format&fit=crop&w=1200&q=85', '[]', 4.6, 88, 3800, 'INR', 3, 13.23, 93.04, '12:00 PM', '10:00 AM', NULL, 'ACTIVE', 1, '2026-10-03 14:50:04', '2026-10-03 14:50:04'),
(13, 'Great Nicobar Eco Wilderness Lodge', 'great-nicobar-eco-lodge', 'ECO_LODGE', 6, 'Exclusive biosphere reserve eco-lodge near Campbell Bay and Galathea National Park.', 'Experience untouched biodiversity, rare endemic wildlife, and southernmost frontier hospitality at our eco lodge.', 'https://images.unsplash.com/photo-1506929562872-bb421503ef21?auto=format&fit=crop&w=1200&q=85', '[]', 4.7, 42, 5500, 'INR', 2, 7, 93.8, '12:00 PM', '10:00 AM', NULL, 'ACTIVE', 0, '2026-10-03 14:50:05', '2026-10-03 14:50:05');
