(10, 'jet-ski', 'Jet Ski Wave Runner', 'High-Speed Jet Ski Wave Adventure', 'Water Sports', 'Port Blair, Havelock & Neil', '10-15 Mins High Speed Ride', 'Easy / Moderate', 4.88, 310, 'Rs.1000/- per head', 'Feel the adrenaline surge as you speed over turquoise waves on a powerful Jet Ski accompanied by a trained safety pilot.', NULL, 1000, 800, 1500, NULL, NULL, 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1920&q=90', '[]', NULL, NULL, NULL, NULL, '["High-Speed Jet Ski Ride across Open Waves","Certified Safety Instructor on-board","High-Grade Life Jacket & Emergency Stop Lanyard","Safety Briefing & Operation Guidance"]', '["GoPro Video recording (available on request ₹250)"]', '["Minimum Age: 10 Years.","Lifejacket mandatory."]', '[]', NULL, NULL, '[]', '[]', 0, 0, 1, 'ACTIVE', '2026-09-27 21:43:15.697 +00:00', '2026-09-27 21:43:15.697 +00:00'),
(11, 'banana-ride', 'Banana / Sofa / Speed Boat / Disco Ride', 'Fun Water Rides (Banana, Sofa, Speed Boat & Disco)', 'Water Sports', 'Elephanta Beach, Havelock & Port Blair', '15-20 Mins Group Splash', 'Easy', 4.85, 340, 'Rs.1000/- per head @ Elephanta Beach, Havelock.', 'Hold on tight as a powerful speedboat pulls your inflatable banana, sofa, or disco tube across ocean swells for maximum fun with family and friends.', NULL, 1000, 800, 1400, NULL, NULL, 'https://images.unsplash.com/photo-1510414842594-a61c69b5ae57?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1510414842594-a61c69b5ae57?auto=format&fit=crop&w=1920&q=90', '[]', NULL, NULL, NULL, NULL, '["Inflatable Tube / Banana / Sofa / Disco Ride Experience","High-Power Speedboat Towing","Safety Lifejackets for all riders","Safety Rescue Boat on standby"]', '["Personal locker rental"]', '["Minimum Age: 6 Years.","Must wear life jacket at all times."]', '[]', NULL, NULL, '[]', '[]', 0, 0, 1, 'ACTIVE', '2026-09-27 21:43:16.499 +00:00', '2026-09-27 21:43:16.499 +00:00'),
(12, 'parasailing', 'Parasailing Ocean Flight', 'High Fly Ocean Parasailing', 'Adventure', 'Havelock & Port Blair', '30 Mins (5-7 mins high air flight + boat ride)', 'Moderate', 4.96, 290, 'Rs.3200/- per head @ Havelock and Rs.3000/- per head @ Port Blair.', 'Soar 300 feet above the turquoise Andaman Sea with a parachute tethered to a high-speed winch boat. Enjoy panoramic views of the islands and an optional sea-dip!', NULL, 3000, 2400, 3800, NULL, NULL, 'https://images.unsplash.com/photo-1506929562872-bb421503ef21?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1506929562872-bb421503ef21?auto=format&fit=crop&w=1920&q=90', '[]', NULL, NULL, NULL, NULL, '["Parasail Flight with Hydraulic Winch Launch & Retrieval","Panoramic 360-degree Aerial Island View","Optional Refreshing Ocean Sea-Dip","Certified Winch Master & Riggers Guidance","Full Safety Harness & Lifejacket"]', '["GoPro video recording (optional ₹500)"]', '["Minimum Age: 8 Years.","Weight limit: 30 kg to 105 kg."]', '[]', NULL, NULL, '[]', '[]', 1, 0, 1, 'ACTIVE', '2026-09-27 21:43:17.372 +00:00', '2026-09-27 21:43:17.372 +00:00'),
(13, 'seakart-adventure', 'Seakart Adventure', 'Seakart Self-Drive Ocean Adventure', 'Adventure', 'Corbyn\'s Cove Beach, Port Blair', '1.5 Hours (20 mins self-drive briefing & cruise)', 'Moderate', 4.97, 130, 'Rs.3500/- per head @ Corbyn\'s Cove Beach, Port Blair.', 'Drive your own high-speed watercraft — an exclusive hybrid of a go-kart and a jet-boat! Steer with steering wheel and paddle accelerator in open sea under instructor supervision.', NULL, 3500, 2800, 4500, NULL, NULL, 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1920&q=90', '[]', NULL, NULL, NULL, NULL, '["Self-Drive Seakart Experience with Steering Controls","Escort Boat with Certified Instructor & Rescue Pilot","Detailed Safety & Maneuver Briefing","Safety Lifejackets & Communication Gear","Coastal Speed Cruise along Corbyn\'s Cove"]', '["Hotel transfer to Corbyn\'s Cove"]', '["Driver Age: 18+ Years (Passenger Age: 6+ Years).","Must follow escort instructor guidelines."]', '[]', NULL, NULL, '[]', '[]', 1, 0, 1, 'ACTIVE', '2026-09-27 21:43:18.032 +00:00', '2026-09-27 21:43:18.032 +00:00'),
(14, 'kayaking', 'Kayaking (Bioluminescent & Mangrove)', 'Kayaking (Night Bioluminescence & Mangrove Explorer)', 'Adventure', 'Port Blair & Havelock', '2.0 Hours Guided Tour', 'Easy', 4.96, 195, 'Rs.3500/- per head @ Port Blair & Havelock.', 'Glide through mystical mangrove channels or experience glowing blue waters under starlit skies on a guided night bioluminescence kayak tour.', NULL, 3500, 2800, 4500, NULL, NULL, 'https://images.unsplash.com/photo-1506929562872-bb421503ef21?auto=format&fit=crop&w=800&q=80', 'https://images.unsplash.com/photo-1506929562872-bb421503ef21?auto=format&fit=crop&w=1920&q=90', '[]', NULL, NULL, NULL, NULL, '["Premium Tandem / Single Sea Kayak & Lightweight Paddles","Certified Naturalist & Kayak Instructor Guide","Night Bioluminescence / Mangrove Exploration","High-grade Lifejacket & Waterproof Dry Bag","Safety Briefing & Technique Coaching"]', '["Transport to creek launch point"]', '["Minimum Age: 8 Years.","Operated during favorable tides and dark moon cycles for bioluminescence."]', '[]', NULL, NULL, '[]', '[]', 1, 0, 1, 'ACTIVE', '2026-09-27 21:43:18.418 +00:00', '2026-09-27 21:43:18.418 +00:00');
