INSERT INTO `Testimonials` (`id`, `name`, `tripType`, `duration`, `destinations`, `rating`, `quote`, `avatar`, `videoThumbnail`, `videoUrl`, `videoDuration`, `tag`, `status`, `createdAt`, `updatedAt`) VALUES
(1, 'Priya & Rohan Sharma', 'Honeymoon & Romantic Escape', '6 Days / 5 Nights', 'Port Blair • Havelock • Neil Island', 5, 'Our 6-day honeymoon in Andaman planned through Andaman Trails was pure paradise! The private catamaran ferry tickets were pre-booked seamlessly, and the candlelight beach dinner at Radhanagar Beach was straight out of a fairy tale. 10/10 recommend for couples!', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=400&q=80', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80', NULL, '01:30', 'HONEYMOON COUPLE', 'ACTIVE', '2026-10-03 19:22:48.715 +00:00', '2026-10-03 19:22:48.715 +00:00'),
(2, 'Dr. Vikram Sengupta', 'Family Leisure Vacation', '5 Days / 4 Nights', 'Port Blair & Havelock Island', 5, 'Traveled with our 8-year-old daughter and elderly parents. The sunset cruise in Port Blair harbor had mesmerizing live acoustic music, and the scuba instructors at Nemo Reef were exceptionally patient with first-timers. World-class hospitality!', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80', NULL, '01:30', 'FAMILY VACATION', 'ACTIVE', '2026-10-03 19:22:49.130 +00:00', '2026-10-03 19:22:49.130 +00:00'),
(3, 'Aditya Verma', 'Adventure & Watersports Group', '7 Days / 6 Nights', 'Havelock • Neil • Baratang', 5, 'Night kayaking through the Havelock mangroves under a canopy of stars with glowing blue bioluminescent plankton is something everyone must do once in their lifetime. Super smooth ferry transfers and scooter rental assistance!', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=400&q=80', 'https://images.unsplash.com/photo-1510414842594-a61c69b5ae57?auto=format&fit=crop&w=800&q=80', NULL, '01:30', 'ADVENTURE SQUAD', 'ACTIVE', '2026-10-03 19:22:49.561 +00:00', '2026-10-03 19:22:49.561 +00:00'),
(4, 'Meera & Rajesh Nair', 'Luxury Beachfront Retreat', '5 Days / 4 Nights', 'Havelock Island Luxury Villa', 5, 'From airport concierge pickup at Port Blair to the private pool villa check-in, everything was ultra-luxurious and punctual. The 24/7 WhatsApp concierge support made us feel completely relaxed and cared for throughout our trip.', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=400&q=80', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80', NULL, '01:30', 'LUXURY GETAWAY', 'ACTIVE', '2026-10-03 19:22:49.993 +00:00', '2026-10-03 19:22:49.993 +00:00'),
(5, 'Karan Malhotra', 'Solo Explorer & Island Hopper', '6 Days / 5 Nights', 'All Andaman Islands Hopping', 5, 'As a solo traveler, inter-island logistics can be stressful, but the instant digital ferry passes and punctual departures between Port Blair, Havelock, and Neil Island made my entire journey effortless and comfortable.', 'https://images.unsplash.com/photo-1492562080023-ab3db95bfbce?auto=format&fit=crop&w=400&q=80', 'https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&w=800&q=80', NULL, '01:30', 'SOLO TRAVELER', 'ACTIVE', '2026-10-03 19:22:50.422 +00:00', '2026-10-03 19:22:50.422 +00:00');
